export type KaminoLendingPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function kaminoLendingProgram() {
  return <T extends KaminoLendingPluginRequirements>(
    client: T
  ): ExtendedClient<T, { kaminoLending: KaminoLendingPlugin }> => {
    return extendClient(client, {
      kaminoLending: <KaminoLendingPlugin>{
        accounts: {
          userState: addSelfFetchFunctions(client, getUserStateCodec()),
          globalConfig: addSelfFetchFunctions(client, getGlobalConfigCodec()),
          lendingMarket: addSelfFetchFunctions(client, getLendingMarketCodec()),
          obligation: addSelfFetchFunctions(client, getObligationCodec()),
          referrerState: addSelfFetchFunctions(client, getReferrerStateCodec()),
          referrerTokenState: addSelfFetchFunctions(client, getReferrerTokenStateCodec()),
          shortUrl: addSelfFetchFunctions(client, getShortUrlCodec()),
          userMetadata: addSelfFetchFunctions(client, getUserMetadataCodec()),
          reserve: addSelfFetchFunctions(client, getReserveCodec()),
          withdrawTicket: addSelfFetchFunctions(client, getWithdrawTicketCodec()),
        },
        instructions: {
          initLendingMarket: (input) =>
            addSelfPlanAndSendFunctions(client, getInitLendingMarketInstruction(input)),
          updateLendingMarket: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateLendingMarketInstruction(input)),
          updateLendingMarketOwner: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateLendingMarketOwnerInstruction(input)),
          initReserve: (input) =>
            addSelfPlanAndSendFunctions(client, getInitReserveInstruction(input)),
          cloneReserveConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getCloneReserveConfigInstruction(input)),
          initFarmsForReserve: (input) =>
            addSelfPlanAndSendFunctions(client, getInitFarmsForReserveInstruction(input)),
          updateReserveConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateReserveConfigInstruction(input)),
          redeemFees: (input) =>
            addSelfPlanAndSendFunctions(client, getRedeemFeesInstruction(input)),
          withdrawProtocolFee: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawProtocolFeeInstruction(input)),
          seedDepositOnInitReserve: (input) =>
            addSelfPlanAndSendFunctions(client, getSeedDepositOnInitReserveInstruction(input)),
          topupReserveRewards: (input) =>
            addSelfPlanAndSendFunctions(client, getTopupReserveRewardsInstruction(input)),
          socializeLoss: (input) =>
            addSelfPlanAndSendFunctions(client, getSocializeLossInstruction(input)),
          socializeLossV2: (input) =>
            addSelfPlanAndSendFunctions(client, getSocializeLossV2Instruction(input)),
          markObligationForDeleveraging: (input) =>
            addSelfPlanAndSendFunctions(client, getMarkObligationForDeleveragingInstruction(input)),
          refreshReserve: (input) =>
            addSelfPlanAndSendFunctions(client, getRefreshReserveInstruction(input)),
          refreshReservesBatch: (input) =>
            addSelfPlanAndSendFunctions(client, getRefreshReservesBatchInstruction(input)),
          calculateCtokenExchangeRate: (input) =>
            addSelfPlanAndSendFunctions(client, getCalculateCtokenExchangeRateInstruction(input)),
          depositReserveLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getDepositReserveLiquidityInstruction(input)),
          redeemReserveCollateral: (input) =>
            addSelfPlanAndSendFunctions(client, getRedeemReserveCollateralInstruction(input)),
          initObligation: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitObligationInstruction({ ...input, feePayer: input.feePayer ?? client.payer })
            ),
          initObligationFarmsForReserve: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitObligationFarmsForReserveInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              })
            ),
          refreshObligationFarmsForReserve: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRefreshObligationFarmsForReserveInstruction(input)
            ),
          refreshObligation: (input) =>
            addSelfPlanAndSendFunctions(client, getRefreshObligationInstruction(input)),
          depositObligationCollateral: (input) =>
            addSelfPlanAndSendFunctions(client, getDepositObligationCollateralInstruction(input)),
          depositObligationCollateralV2: (input) =>
            addSelfPlanAndSendFunctions(client, getDepositObligationCollateralV2Instruction(input)),
          withdrawObligationCollateral: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawObligationCollateralInstruction(input)),
          withdrawObligationCollateralV2: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawObligationCollateralV2Instruction(input)
            ),
          borrowObligationLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getBorrowObligationLiquidityInstruction(input)),
          borrowObligationLiquidityV2: (input) =>
            addSelfPlanAndSendFunctions(client, getBorrowObligationLiquidityV2Instruction(input)),
          repayObligationLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getRepayObligationLiquidityInstruction(input)),
          repayObligationLiquidityV2: (input) =>
            addSelfPlanAndSendFunctions(client, getRepayObligationLiquidityV2Instruction(input)),
          repayAndWithdrawAndRedeem: (input) =>
            addSelfPlanAndSendFunctions(client, getRepayAndWithdrawAndRedeemInstruction(input)),
          depositAndWithdraw: (input) =>
            addSelfPlanAndSendFunctions(client, getDepositAndWithdrawInstruction(input)),
          depositReserveLiquidityAndObligationCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositReserveLiquidityAndObligationCollateralInstruction(input)
            ),
          depositReserveLiquidityAndObligationCollateralV2: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositReserveLiquidityAndObligationCollateralV2Instruction(input)
            ),
          withdrawObligationCollateralAndRedeemReserveCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawObligationCollateralAndRedeemReserveCollateralInstruction(input)
            ),
          withdrawObligationCollateralAndRedeemReserveCollateralV2: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawObligationCollateralAndRedeemReserveCollateralV2Instruction(input)
            ),
          liquidateObligationAndRedeemReserveCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLiquidateObligationAndRedeemReserveCollateralInstruction(input)
            ),
          liquidateObligationAndRedeemReserveCollateralV2: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLiquidateObligationAndRedeemReserveCollateralV2Instruction(input)
            ),
          flashRepayReserveLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getFlashRepayReserveLiquidityInstruction(input)),
          flashBorrowReserveLiquidity: (input) =>
            addSelfPlanAndSendFunctions(client, getFlashBorrowReserveLiquidityInstruction(input)),
          requestElevationGroup: (input) =>
            addSelfPlanAndSendFunctions(client, getRequestElevationGroupInstruction(input)),
          initReferrerTokenState: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitReferrerTokenStateInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          initUserMetadata: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitUserMetadataInstruction({ ...input, feePayer: input.feePayer ?? client.payer })
            ),
          withdrawReferrerFees: (input) =>
            addSelfPlanAndSendFunctions(client, getWithdrawReferrerFeesInstruction(input)),
          initReferrerStateAndShortUrl: (input) =>
            addSelfPlanAndSendFunctions(client, getInitReferrerStateAndShortUrlInstruction(input)),
          deleteReferrerStateAndShortUrl: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDeleteReferrerStateAndShortUrlInstruction(input)
            ),
          setObligationOrder: (input) =>
            addSelfPlanAndSendFunctions(client, getSetObligationOrderInstruction(input)),
          setBorrowOrder: (input) =>
            addSelfPlanAndSendFunctions(client, getSetBorrowOrderInstruction(input)),
          setBorrowOrderV2: (input) =>
            addSelfPlanAndSendFunctions(client, getSetBorrowOrderV2Instruction(input)),
          updateObligationConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateObligationConfigInstruction(input)),
          rolloverFixedTermBorrow: (input) =>
            addSelfPlanAndSendFunctions(client, getRolloverFixedTermBorrowInstruction(input)),
          fillBorrowOrder: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillBorrowOrderInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          fillBorrowOrderV2: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFillBorrowOrderV2Instruction({ ...input, payer: input.payer ?? client.payer })
            ),
          initiateObligationOwnershipTransfer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitiateObligationOwnershipTransferInstruction(input)
            ),
          approveObligationOwnershipTransfer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApproveObligationOwnershipTransferInstruction(input)
            ),
          acceptObligationOwnership: (input) =>
            addSelfPlanAndSendFunctions(client, getAcceptObligationOwnershipInstruction(input)),
          abortObligationOwnershipTransfer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAbortObligationOwnershipTransferInstruction(input)
            ),
          enqueueToWithdraw: (input) =>
            addSelfPlanAndSendFunctions(client, getEnqueueToWithdrawInstruction(input)),
          withdrawQueuedLiquidity: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawQueuedLiquidityInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              })
            ),
          recoverInvalidTicketCollateral: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecoverInvalidTicketCollateralInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              })
            ),
          cancelWithdrawTicket: (input) =>
            addSelfPlanAndSendFunctions(client, getCancelWithdrawTicketInstruction(input)),
          initGlobalConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitGlobalConfigInstruction({ ...input, payer: input.payer ?? client.payer })
            ),
          updateGlobalConfig: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateGlobalConfigInstruction(input)),
          updateGlobalConfigAdmin: (input) =>
            addSelfPlanAndSendFunctions(client, getUpdateGlobalConfigAdminInstruction(input)),
          idlMissingTypes: (input) =>
            addSelfPlanAndSendFunctions(client, getIdlMissingTypesInstruction(input)),
        },
        identifyAccount: identifyKaminoLendingAccount,
        identifyInstruction: identifyKaminoLendingInstruction,
        parseInstruction: parseKaminoLendingInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
